#!/usr/bin/env python3
"""Validate frozen work-order metadata and repository scope."""

from __future__ import annotations

import argparse
import hashlib
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
ID_RE = re.compile(r"^WO-[A-Z0-9]+(?:-[A-Z0-9]+)*$")
SHA_RE = re.compile(r"^[0-9a-f]{40}$")


class ValidationError(ValueError):
    """A work order or changed-path set violates its contract."""


def load_wo(wo_id: str, root: Path = ROOT) -> tuple[dict[str, str], str]:
    if not ID_RE.fullmatch(wo_id):
        raise ValidationError("invalid WO ID")
    path = root / "work" / f"{wo_id}.md"
    raw = path.read_bytes()
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValidationError("work order is not UTF-8") from exc
    if not content.startswith("---\n") or "\n---\n" not in content[4:]:
        raise ValidationError("missing front matter")
    boundary = content.find("\n---\n", 4)
    fields: dict[str, str] = {}
    for line in content[4:boundary].splitlines():
        if ":" not in line:
            raise ValidationError("malformed front matter")
        key, value = line.split(":", 1)
        if key in fields:
            raise ValidationError(f"duplicate front matter key: {key}")
        fields[key] = value.strip()
    expected = fields.get("spec_sha256", "")
    frozen = re.sub(r"(?m)^spec_sha256: [0-9a-f]{64}\n", "", content, count=1)
    actual = hashlib.sha256(frozen.encode("utf-8")).hexdigest()
    if not re.fullmatch(r"[0-9a-f]{64}", expected) or expected != actual:
        raise ValidationError("frozen spec SHA-256 mismatch")
    if fields.get("id") != wo_id or not fields.get("revision", "").isdigit():
        raise ValidationError("front matter ID or revision mismatch")
    if not re.fullmatch(r"[0-9a-f]{40}", fields.get("base_sha", "")):
        raise ValidationError("base_sha must be a full lowercase git SHA-1")
    return fields, expected


def changed_path_allowed(path: str, allowed: list[str], protected: list[str]) -> bool:
    from pathlib import PurePosixPath

    candidate = PurePosixPath(path)
    if candidate.is_absolute() or ".." in candidate.parts or "\\" in path:
        return False
    if any(candidate.match(pattern) for pattern in protected):
        return False
    return any(candidate.match(pattern) for pattern in allowed)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("wo_id", nargs="?")
    parser.add_argument("--ready", action="store_true")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args(argv)
    try:
        if args.self_test:
            fields, spec_hash = load_wo("WO-BOOT-04")
            if fields.get("status") != "READY" or len(spec_hash) != 64:
                raise ValidationError("self-test WO is not frozen READY")
            allow = ["scripts/**"]
            protected = ["scripts/oracle/**"]
            if not changed_path_allowed("scripts/wo_driver.py", allow, protected):
                raise ValidationError("allowlist self-test rejected an allowed path")
            if changed_path_allowed("scripts/oracle/frozen.py", allow, protected):
                raise ValidationError("allowlist self-test accepted a protected path")
            print("frozen work order valid")
        else:
            if not args.wo_id:
                parser.error("wo_id is required unless --self-test is used")
            fields, spec_hash = load_wo(args.wo_id)
            if args.ready and fields.get("status") != "READY":
                raise ValidationError("work order is not READY")
            print(f"valid {args.wo_id} revision {fields['revision']} sha256 {spec_hash}")
    except (OSError, ValidationError) as exc:
        print(f"work order error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Work-order orchestration primitives; shell entry points delegate here."""

from __future__ import annotations

import argparse
import fcntl
import hashlib
import json
import os
import re
import signal
import subprocess
import sys
import tempfile
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Sequence

try:
    from .wo_validate import ID_RE, ROOT, ValidationError, changed_path_allowed, load_wo
except ImportError:
    from wo_validate import ID_RE, ROOT, ValidationError, changed_path_allowed, load_wo

REQUIRED_EXEC_FLAGS = (
    "--model", "--config", "--sandbox", "--ask-for-approval", "--json",
    "--output-schema", "--output-last-message", "--image",
)
SESSION_RE = re.compile(r"^[0-9a-fA-F-]{36}$")


class RunnerError(RuntimeError):
    """A run failed a safety or integrity check."""


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def preflight(codex: str, runner: Any = subprocess.run) -> tuple[str, str, str]:
    version = runner([codex, "--version"], capture_output=True, text=True, check=True).stdout.strip()
    outputs = []
    for args in ([codex, "exec", "--help"], [codex, "exec", "resume", "--help"]):
        result = runner(args, capture_output=True, text=True, check=True)
        outputs.append(result.stdout + result.stderr)
    missing = [flag for flag in REQUIRED_EXEC_FLAGS if flag not in outputs[0]]
    missing.extend(flag for flag in REQUIRED_EXEC_FLAGS if flag not in outputs[1])
    if missing:
        raise RunnerError("installed Codex CLI lacks required flags: " + ", ".join(sorted(set(missing))))
    return version, outputs[0], outputs[1]


def parse_session_id(jsonl: str) -> str | None:
    for line in jsonl.splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(event, dict) and event.get("type") == "thread.started":
            value = event.get("thread_id")
            if isinstance(value, str) and SESSION_RE.fullmatch(value):
                return value
    return None


def validate_json_schema(instance: Any, schema: dict[str, Any]) -> bool:
    """Small fail-closed validator for the JSON Schema subset used by reports."""
    if "enum" in schema and instance not in schema["enum"]:
        return False
    expected = schema.get("type")
    if expected:
        types = expected if isinstance(expected, list) else [expected]
        checks = {
            "object": lambda x: isinstance(x, dict), "array": lambda x: isinstance(x, list),
            "string": lambda x: isinstance(x, str), "integer": lambda x: type(x) is int,
            "number": lambda x: type(x) in (int, float), "boolean": lambda x: type(x) is bool,
            "null": lambda x: x is None,
        }
        if not any(t in checks and checks[t](instance) for t in types):
            return False
    if isinstance(instance, dict):
        required = schema.get("required", [])
        if any(key not in instance for key in required):
            return False
        props = schema.get("properties", {})
        if schema.get("additionalProperties") is False and instance.keys() - props.keys():
            return False
        for key, value in instance.items():
            if key in props and not validate_json_schema(value, props[key]):
                return False
    if isinstance(instance, list) and "items" in schema:
        if any(not validate_json_schema(item, schema["items"]) for item in instance):
            return False
    if isinstance(instance, str):
        if len(instance) < schema.get("minLength", 0) or len(instance) > schema.get("maxLength", sys.maxsize):
            return False
        if "pattern" in schema and re.search(schema["pattern"], instance) is None:
            return False
    if type(instance) in (int, float):
        if instance < schema.get("minimum", float("-inf")) or instance > schema.get("maximum", float("inf")):
            return False
    return True


def append_jsonl_atomic(path: Path, item: dict[str, Any], interrupted: bool = False) -> None:
    """Append atomically via replacement, retaining existing mode and contents."""
    path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = path.with_suffix(path.suffix + ".lock")
    with lock_path.open("a+b") as lock:
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
        old = path.read_bytes() if path.exists() else b""
        if old and not old.endswith(b"\n"):
            raise RunnerError("JSONL cache has a truncated final record")
        line = json.dumps(item, sort_keys=True, separators=(",", ":")).encode() + b"\n"
        fd, name = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.")
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(old)
                stream.write(line)
                stream.flush()
                if interrupted:
                    raise OSError("injected interruption before fsync")
                os.fsync(stream.fileno())
            os.replace(name, path)
        finally:
            if os.path.exists(name):
                os.unlink(name)


def run_process(argv: Sequence[str], cwd: Path, timeout_s: float, stdout_path: Path,
                stderr_path: Path, env: dict[str, str] | None = None) -> tuple[int, float, str]:
    start = time.monotonic()
    proc = subprocess.Popen(list(argv), cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, env=env, start_new_session=True)
    try:
        out, err = proc.communicate(timeout=timeout_s)
    except subprocess.TimeoutExpired:
        os.killpg(proc.pid, signal.SIGTERM)
        try:
            out, err = proc.communicate(timeout=30)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid, signal.SIGKILL)
            out, err = proc.communicate()
        code = 124
    else:
        code = int(proc.returncode)
    stdout_path.write_bytes(out)
    stderr_path.write_bytes(err)
    return code, time.monotonic() - start, out.decode("utf-8", errors="replace")


def spec_key(fields: dict[str, str], spec: str, worktree: Path) -> dict[str, Any]:
    return {"wo_id": fields["id"], "revision": int(fields["revision"]),
            "spec_sha256": spec, "worktree_path": str(worktree), "base_sha": fields["base_sha"]}


def ensure_descendant(root: Path, base: str, head: str) -> bool:
    return subprocess.run(["git", "merge-base", "--is-ancestor", base, head], cwd=root,
                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0


def git_paths(root: Path, base: str, head: str) -> list[str]:
    result = subprocess.run(["git", "diff", "--name-only", "-z", base, head], cwd=root,
                            capture_output=True, check=True)
    return [part.decode("utf-8") for part in result.stdout.split(b"\0") if part]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("new", "resume", "verify"))
    parser.add_argument("wo_id")
    parser.add_argument("identity", nargs="?")
    parser.add_argument("--codex", default="codex")
    parser.add_argument("--timeout", type=float, default=7200)
    parser.add_argument("--image", action="append", default=[])
    args = parser.parse_args(argv)
    try:
        if sys.platform != "darwin":
            raise RunnerError("work-order runners support macOS only")
        if not ID_RE.fullmatch(args.wo_id):
            raise RunnerError("invalid WO ID")
        fields, spec_hash = load_wo(args.wo_id)
        if args.mode != "verify" and fields.get("status") != "READY":
            raise RunnerError("work order is not READY")
        preflight(args.codex)
        raise RunnerError("execution is not enabled until work-order command plan is reviewed")
    except (OSError, subprocess.SubprocessError, ValidationError, RunnerError) as exc:
        print(f"runner error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

